-- Run in Supabase SQL Editor for cloud mode.
create table if not exists public.users (
 user_id bigint generated by default as identity primary key,
 name text not null, email text unique not null, password_hash text not null, role text not null check(role in ('student','teacher')), created_at timestamptz default now()
);
create table if not exists public.courses (course_id bigint generated by default as identity primary key, course_name text not null, teacher_id bigint references public.users(user_id), created_at timestamptz default now());
create table if not exists public.assignments (assignment_id bigint generated by default as identity primary key, course_id bigint references public.courses(course_id), title text not null, description text not null, deadline timestamptz not null, max_marks int not null, created_by bigint references public.users(user_id), allowed_file_types text default 'pdf,docx', max_file_size_mb int default 10, created_at timestamptz default now());
create table if not exists public.submissions (submission_id bigint generated by default as identity primary key, assignment_id bigint references public.assignments(assignment_id), student_id bigint references public.users(user_id), file_name text not null, file_url text, storage_path text not null, submitted_at timestamptz default now(), submission_status text not null, marks int, feedback text, graded_at timestamptz);
create index if not exists idx_assignments_deadline on public.assignments(deadline);
create index if not exists idx_submissions_student on public.submissions(student_id);
